// Avoid this: Synchronized blocks cause pinning
public synchronized void criticalSection() { 
    // ... blocking I/O here will pin the carrier thread
}

// Use this: ReentrantLock allows the carrier to unmount
private final ReentrantLock lock = new ReentrantLock();
public void safeSection() {
    lock.lock();
    try {
        // ... blocking I/O here is safe and will not pin
    } finally {
        lock.unlock();
    }
}
